const getSizeMultiplier = (index: number, total: number) : number => {
  if (index === total - 3) return 2.8;
  if (index === total - 2) return 2.8;
  if (index === total - 1) return 2.8;
  return 1.0;
}

const DURATION = 5500;

interface LoaderProps {
  onComplete: () => void;
}

export default function WebsiteLoader({ onComplete }: LoaderProps) {
  const [frame, setFrame] = useState(0);
  const [exiting, setExiting] = useState(false);

  const total = stages.length;
  const isSecondToLast = frame === total - 3;
  const isLast = frame === total - 1;

  useEffect(() => {
    const interval = DURATION / stages.length;
    const timer = setInterval(() => {
      setFrame(f => {
        if (f >= stages.length - 1) {
          clearInterval(timer);
          return f;
        }
        return f + 1;
      });
    }, interval);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    if (isLast) {
      setTimeout(() => setExiting(true), 600);
      setTimeout(onComplete, 1100);
    }
  }, [frame]);

  const progressFrame = Math.min(frame, total - 4);
  const progress = (progressFrame / (total - 4)) * 100;

  const barHidden = frame >= total - 3;

  const multiplier = getSizeMultiplier(frame, total);

  // Base size
  const baseSize = 400; // px (maxWidth/maxHeight)
  const currentSize = baseSize * multiplier;

  const signVisible = frame >= 1;
  const signHidden = frame >= total - 4;

  return (
    <>
      <style>{`
        @keyframes growIn {
          from { transform: scale(0.6); opacity: 0.4; }
          to   { transform: scale(1);   opacity: 1;   }
        }
        .grow-in {
          animation: growIn 0.5s ease-out forwards;
        }
      `}</style>

      <div className={`
        fixed inset-0 bg-[#f8f5ef] z-50
        flex flex-col items-center justify-end pb-[12%]
        transition-opacity duration-500
        ${exiting ? 'opacity-0' : 'opacity-100'}
      `}>

        <div 
          className="
            absolute
            top-56
            flex
            flex-col
            justify-center
            w-[65%]
            text-center
            items-center
            gap-[1.5rem]
          "
          style={{
            transform: !signVisible ? 'translateY(-40px)' : signHidden ? 'translateY(40px)' : 'translateY(0)',
            opacity: signVisible && !signHidden ? 1 : 0,
            transition: 'transform 0.2s ease-out, opacity 0.2s ease-out'
          }}
        >
          <h1 className="
            font-heading
            font-bold
            leading-tight
            text-[1.5rem]
            md:text-[2.5rem]
            text-[#0d1a11]
          ">
            Academically serious. Endearingly unconventional.
          </h1>
          <img src={metoloSign} className="w-22 h-16" />
        </div>

        {/* Container — size animates up for second-to-last, snaps for last */}
        <div
          style={{
            width:  `min(${currentSize}px, ${40 * multiplier}vw)`,
            height: `min(${currentSize}px, ${40 * multiplier}vw)`,
            maxWidth:  `${baseSize * multiplier}px`,
            maxHeight: `${baseSize * multiplier}px`,
            position: 'relative',
            overflow: 'visible',
            transition: 'width 2s ease-out, height 2s ease-out',
          }}
        >
          {stages.map((svg, i) => (
            <div
              key={i}
              className={`
                absolute inset-0
                ${i === frame && isSecondToLast ? 'grow-in' : ''}
              `}
              style={{
                opacity: i === frame ? 1 : 0,
                transition: 'opacity 0.35s ease',
                willChange: 'opacity',
              }}
              dangerouslySetInnerHTML={{
                __html: svg
                  ? svg.replace(
                      '<svg ',
                      '<svg style="width:100%;height:100%;" preserveAspectRatio="xMidYMax meet" '
                    )
                  : '<svg width="800" height="800" viewBox="0 0 800 800"/>',
              }}
            />
          ))}
        </div>

        {/* Ground line + progress */}
        <div
          className="mt-0 relative"
          style={{ 
            width: '80vw', 
            maxWidth: '900px',
            transform: barHidden ? 'translateY(40px)' : 'translateY(0)',
            opacity: barHidden ? 0 : 1,
            transition: 'transform 0.2s ease-in, opacity 0.2s ease-in',
          }}
        >
          <div className="w-full h-[8px] bg-[#20422a] opacity-20" />
          <div
            className="absolute top-0 left-0 h-[8px] bg-[#20422a] transition-all duration-500 ease-out"
            style={{ width: `${progress}%` }}
          />
          <p className="font-body text-[0.875rem] tracking-widest text-[#535250] mt-5 text-center uppercase">
            Loading {Math.round(progress)}%
          </p>
        </div>
      </div>
    </>
  );
}